import { defineComponent } from "../../lib/ecs-js/index.js";

/**
 * Runtime polymorph policy hooks for entities whose transform behavior is not
 * fully described by monster authoring data. Resistance is a probability-like
 * score in [0, 1]; stability is reserved for future side-effect/fumble logic.
 */
export const PolymorphProfile = defineComponent(
  "PolymorphProfile",
  {
    resistance: 0,
    stability: 0,
  },
  {
    validate(rec) {
      if (!rec || typeof rec !== "object") return false;
      rec.resistance = Math.max(0, Math.min(1, Number(rec.resistance || 0)));
      rec.stability = Math.max(0, Number(rec.stability || 0));
      return true;
    },
  },
);

